#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <limits>
#include <string_view>
#include <vector>
#include "vektoryum/ml/artifact_digest.hpp"
#include "vektoryum/training/benchmark_result_contract.hpp"
namespace { int failures=0; void expect_true(bool c,std::string_view n){if(!c){++failures;std::cerr<<"[FAIL] "<<n<<'\n';}else std::cout<<"[PASS] "<<n<<'\n';}
std::vector<std::uint8_t> artifact_bytes(){return {0x56U,0x45U,0x4BU,0x54U,0x4FU,0x52U,0x59U,0x55U,0x4DU};}
vektoryum::training::BenchmarkResultManifest valid_manifest(const std::vector<std::uint8_t>& a){using namespace vektoryum::training; BenchmarkResultManifest m; m.schema_version="vektoryum-benchmark-result-v1";m.benchmark_id="stage8-fidelity";m.benchmark_version="1";m.run_id="run-001";m.dataset_id="dataset-a";m.dataset_version="2026-08";m.model_id="vektoryum-reference";m.model_version="1";m.architecture_revision="arch-v1";m.training_code_revision="train-commit-001";m.degradation_pipeline_revision="degrade-v1";m.training_artifact_sha256=std::string(64,'a');m.runtime_id="vektoryum-reference-runtime";m.runtime_version="1";m.seed=0x5A17U;m.evaluated_samples=128U;m.metrics={{"alpha_iou","1","ratio","mean",0.997},{"rgb_mae","1","normalized","mean",0.002}};m.artifact_sha256=vektoryum::ml::sha256_hex(a);return m;}}
int main(){using namespace vektoryum::training;const auto artifact=artifact_bytes();const auto baseline=valid_manifest(artifact);expect_true(validate_benchmark_result(baseline,artifact).ok(),"benchmark result with production model provenance is accepted");const auto report=canonical_benchmark_report(baseline);expect_true(report==canonical_benchmark_report(baseline),"canonical benchmark report is byte deterministic");expect_true(report.find("training_artifact_sha256=")!=std::string::npos,"report binds metrics to training artifact");BenchmarkResultManifest x=baseline;x.architecture_revision.clear();expect_true(validate_benchmark_result(x,artifact).error==BenchmarkResultError::MissingArchitectureRevision,"missing architecture revision rejected");x=baseline;x.training_code_revision.clear();expect_true(validate_benchmark_result(x,artifact).error==BenchmarkResultError::MissingTrainingCodeRevision,"missing training code revision rejected");x=baseline;x.degradation_pipeline_revision.clear();expect_true(validate_benchmark_result(x,artifact).error==BenchmarkResultError::MissingDegradationPipelineRevision,"missing degradation revision rejected");x=baseline;x.training_artifact_sha256.clear();expect_true(validate_benchmark_result(x,artifact).error==BenchmarkResultError::MissingTrainingArtifactChecksum,"missing training artifact checksum rejected");x=baseline;x.training_artifact_sha256="bad";expect_true(validate_benchmark_result(x,artifact).error==BenchmarkResultError::InvalidTrainingArtifactChecksum,"invalid training artifact checksum rejected");x=baseline;x.metrics[0].unit.clear();expect_true(validate_benchmark_result(x,artifact).error==BenchmarkResultError::MissingMetricMetadata,"missing metric metadata rejected");x=baseline;x.metrics[1].name=x.metrics[0].name;expect_true(validate_benchmark_result(x,artifact).error==BenchmarkResultError::DuplicateMetricName,"duplicate metrics rejected");x=baseline;auto first=x.metrics[0];x.metrics[0]=x.metrics[1];x.metrics[1]=first;expect_true(validate_benchmark_result(x,artifact).error==BenchmarkResultError::NonDeterministicMetricOrder,"noncanonical metric order rejected");x=baseline;x.metrics[0].value=std::numeric_limits<double>::infinity();expect_true(validate_benchmark_result(x,artifact).error==BenchmarkResultError::NonFiniteMetricValue,"nonfinite metric rejected");x=baseline;x.evaluated_samples=0;expect_true(validate_benchmark_result(x,artifact).error==BenchmarkResultError::ZeroEvaluatedSamples,"zero samples rejected");BenchmarkResultLimits l;l.max_evaluated_samples=64;expect_true(validate_benchmark_result(baseline,artifact,l).error==BenchmarkResultError::SampleBudgetExceeded,"sample budget enforced");l=BenchmarkResultLimits{};l.max_artifact_bytes=4;expect_true(validate_benchmark_result(baseline,artifact,l).error==BenchmarkResultError::ArtifactBudgetExceeded,"artifact budget enforced");auto tampered=artifact;tampered[0]^=1;expect_true(validate_benchmark_result(baseline,tampered).error==BenchmarkResultError::ArtifactDigestMismatch,"tampered result artifact rejected");x=baseline;x.artifact_sha256="bad";expect_true(validate_benchmark_result(x,artifact).error==BenchmarkResultError::InvalidArtifactDigest,"invalid result digest rejected");expect_true(validate_benchmark_result(baseline,{}).error==BenchmarkResultError::EmptyArtifact,"missing result artifact rejected");if(failures){std::cerr<<failures<<" test(s) failed\n";return EXIT_FAILURE;}std::cout<<"All benchmark contract tests passed\n";return EXIT_SUCCESS;}
